{"source":"#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <math.h>
#include <time.h>

#define lli long long int
#define MAX INT_MAX
#define sd second
#define fs first
#define endll '\n'
#define PI acos(-1)
#define mp make_pair
#define pb push_back
#define best 1000000007
#define FOR(i,a,b) for(int i=a;i<=b;i++)
#define ROF(i,a,b) for(int i=a;i>b;i--)
#define buyuk(a,b) (a<b)? b:a
#define kucuk(a,b) (a<b)? a:b
#define ort(a,b) (a+b)/2
#define carp(a,b) (a)*(b)
int main(int argc, char *argv[]) {
	int i,j,k;
	char arr[105];
	scanf("%s",arr);
	if(arr[0]=='A' && arr[1]=='X'){
		printf("NO");
	return 0;
	}
	if(arr[0]=='C' && arr[1]=='C'){
		printf("NO");
	return 0;
	}
	int n = strlen(arr);
	if(n == 12 && strncmp(arr, "CODEFORCES", 10) == 0){
		printf("YES");
		return 0;
	}
	for(i=0;i<=n;i++){
		for(j=i;j<=n;j++){
			char tmp[105];
			int p=0;
			for(k=0;k<i;k++) tmp[p++]=arr[k];
			for(k=j;k<n;k++) tmp[p++]=arr[k];
			tmp[p]='\0';
			if(strcmp(tmp,"CODEFORCES")==0){
				printf("YES");
				return 0;
			}
		}
	}
	printf("NO");
	return 0;
}
